<?php
require_once __DIR__ . '/../config/seguridad_web.php';

if(session_status()!==PHP_SESSION_ACTIVE)session_start();
require_once __DIR__.'/../config/db.php';
if(empty($_SESSION['usuario_id'])){header('Location: /auth/login.php');exit;}
if(empty($_SESSION['usuario_es_admin'])){http_response_code(403);exit('Acceso exclusivo para el administrador. <a href="/index.php">Regresar al Inicio</a>');}
$propietario=(int)$_SESSION['usuario_id'];
$texto=is_string($_GET['buscar']??null)?mb_substr(trim($_GET['buscar']),0,100):'';
$accion=in_array($_GET['accion']??'', ['REGISTRO','PAGO','MODIFICACIÓN','ELIMINACIÓN'],true)?$_GET['accion']:'';
$desde=is_string($_GET['desde']??null)?$_GET['desde']:'';$hasta=is_string($_GET['hasta']??null)?$_GET['hasta']:'';
$fechaValida=function($v){$d=DateTimeImmutable::createFromFormat('!Y-m-d',$v);return $d&&$d->format('Y-m-d')===$v;};
$aviso='';if(($desde&&!$fechaValida($desde))||($hasta&&!$fechaValida($hasta))||($desde&&$hasta&&$desde>$hasta)){$aviso='Revisa el rango de fechas.';$desde='';$hasta='';}
$where=' WHERE propietario_id=?';$args=[$propietario];
if($texto!==''){$where.=" AND (actor_nombre LIKE ? OR COALESCE(JSON_UNQUOTE(JSON_EXTRACT(despues,'$.descripcion')),JSON_UNQUOTE(JSON_EXTRACT(antes,'$.descripcion'))) LIKE ?)";array_push($args,'%'.$texto.'%','%'.$texto.'%');}
if($accion!==''){$where.=' AND accion=?';$args[]=$accion;}
$zona=new DateTimeZone('America/New_York');$utc=new DateTimeZone('UTC');
if($desde){$where.=' AND creado_en>=?';$args[]=(new DateTimeImmutable($desde,$zona))->setTimezone($utc)->format('Y-m-d H:i:s');}
if($hasta){$where.=' AND creado_en<?';$args[]=(new DateTimeImmutable($hasta,$zona))->modify('+1 day')->setTimezone($utc)->format('Y-m-d H:i:s');}
$q=$pdo->prepare('SELECT COUNT(*) FROM historial_gastos'.$where);$q->execute($args);$total=(int)$q->fetchColumn();
$paginas=max(1,(int)ceil($total/20));$pagina=min($paginas,max(1,(int)($_GET['pagina']??1)));
$q=$pdo->prepare('SELECT * FROM historial_gastos'.$where.' ORDER BY id DESC LIMIT 20 OFFSET '.(($pagina-1)*20));$q->execute($args);$movimientos=$q->fetchAll(PDO::FETCH_ASSOC);
$e=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
$etiquetas=['descripcion'=>'Descripción','categoria'=>'Categoría','tipo'=>'Tipo','amount'=>'Monto','due_date'=>'Vencimiento','payment_date'=>'Fecha de pago','confirmation'=>'Confirmación','pagado'=>'Pagado','banco_pago'=>'Banco de pago','metodo_pago'=>'Método de pago','tarjeta_id'=>'ID tarjeta de origen','tarjeta_destino_id'=>'ID tarjeta abonada','mantenimiento_id'=>'ID pago programado','notes'=>'Notas','validado'=>'Validado','banco'=>'Banco'];
?>
<style>
.historial-volver{display:inline-flex;align-items:center;min-height:44px;padding:10px 16px;margin-bottom:18px;border:1px solid var(--ui-border,#cddae9);border-radius:8px;text-decoration:none;background:var(--ui-panel,#fff);color:var(--ui-text,#163047)}.historial-finanzas{max-width:1100px;margin:auto}.historial-finanzas form{display:flex;gap:12px;align-items:end;flex-wrap:wrap;margin:20px 0}.historial-finanzas label{display:flex;flex-direction:column;gap:6px;font-size:13px;min-width:0}.historial-finanzas input,.historial-finanzas select{padding:10px;min-height:44px;border:1px solid #d0dae7;border-radius:8px;font:inherit;max-width:100%}.historial-finanzas button{padding:11px 18px;background:#1669b8;color:white;border:0;border-radius:8px;cursor:pointer}.movimiento-card{background:var(--surface,#fff);color:var(--text,#163047);border:1px solid #cddae9;border-radius:12px;padding:20px;margin:16px 0;overflow-wrap:anywhere}.movimiento-card h3{font-size:18px;margin:8px 0}.movimiento-meta{color:#576d82;font-size:13px;line-height:1.7}.movimiento-card summary{cursor:pointer;padding:12px 0;font-weight:600}.movimiento-card table{width:100%;border-collapse:collapse;font-size:13px}.movimiento-card td,.movimiento-card th{padding:10px;text-align:left;border-bottom:1px solid #dce5ef;overflow-wrap:anywhere}.movimiento-card details{margin-top:10px}.historial-paginas{display:flex;gap:20px;justify-content:space-between;flex-wrap:wrap;margin:20px 0}.movimiento-tipo{display:inline-block;padding:4px 8px;border-radius:6px;background:#e8f2fc;color:#175d9c;font-size:12px;font-weight:bold}@media(max-width:760px){.historial-finanzas form{display:grid;grid-template-columns:1fr 1fr}.historial-finanzas input,.historial-finanzas select{width:100%;font-size:16px}.movimiento-card{padding:16px}.movimiento-card table,.movimiento-card tbody,.movimiento-card tr,.movimiento-card td{display:block;width:100%}.movimiento-card thead{display:none}.movimiento-card tr{margin-bottom:12px;border:1px solid #dce5ef;border-radius:8px;padding:8px}.movimiento-card td:before{content:attr(data-label);display:block;font-size:11px;font-weight:600;color:#576d82;margin-bottom:3px}}@media(max-width:400px){.historial-finanzas form{grid-template-columns:1fr}}
</style>
<section class="historial-finanzas"><a class="historial-volver" href="/index.php">← Regresar al Inicio</a><h1>Historial de movimientos</h1><p>Consulta quién registró o cambió un gasto o pago. Se muestran las operaciones realizadas desde la activación de esta función.</p>
<form method="get" action="/index.php"><input type="hidden" name="menu" value="historial_movimientos"><label>Buscar<input name="buscar" placeholder="Persona o descripción" value="<?= $e($texto) ?>"></label><label>Movimiento<select name="accion"><option value="">Todos</option><?php foreach(['REGISTRO','PAGO','MODIFICACIÓN','ELIMINACIÓN'] as $opcion): ?><option value="<?= $e($opcion) ?>" <?= $opcion===$accion?'selected':'' ?>><?= $e($opcion) ?></option><?php endforeach; ?></select></label><label>Desde<input type="date" name="desde" value="<?= $e($desde) ?>"></label><label>Hasta<input type="date" name="hasta" value="<?= $e($hasta) ?>"></label><button type="submit">Filtrar</button><a href="/index.php?menu=historial_movimientos">Limpiar</a></form>
<?php if($aviso): ?><p role="alert"><?= $e($aviso) ?></p><?php endif; ?><p><?= $total ?> movimiento(s)</p>
<?php foreach($movimientos as $movimiento): $antes=json_decode($movimiento['antes']??'null',true);$despues=json_decode($movimiento['despues']??'null',true);$datos=$despues??$antes; ?>
<article class="movimiento-card"><span class="movimiento-tipo"><?= $e($movimiento['accion']) ?></span><h3 data-no-translate><?= $e($datos['descripcion']??'Gasto') ?></h3><p class="movimiento-meta"><strong data-no-translate><?= $e($movimiento['actor_nombre']) ?></strong> · <?= $e((new DateTimeImmutable($movimiento['creado_en'],$utc))->setTimezone($zona)->format('d/m/Y H:i:s')) ?><br>Gasto #<?= (int)$movimiento['gasto_id'] ?> · Monto: <?= $e($datos['amount']??'') ?></p>
<details><summary><?= $antes&&$despues?'Ver qué cambió':'Ver datos del movimiento' ?></summary><table><thead><tr><th>Campo</th><?php if($antes&&$despues): ?><th>Antes</th><th>Después</th><?php else: ?><th>Valor</th><?php endif; ?></tr></thead><tbody>
<?php foreach($etiquetas as $campo=>$etiqueta): if($antes&&$despues&&($antes[$campo]??null)===($despues[$campo]??null))continue; ?><tr><td data-label="Campo"><?= $e($etiqueta) ?></td><?php if($antes&&$despues): ?><td data-label="Antes"><?= $e($antes[$campo]??'Sin valor') ?></td><td data-label="Después"><?= $e($despues[$campo]??'Sin valor') ?></td><?php else: ?><td data-label="Valor"><?= $e($datos[$campo]??'Sin valor') ?></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></details></article><?php endforeach; ?>
<?php if(!$movimientos): ?><p>No hay movimientos que coincidan con estos filtros.</p><?php endif; ?>
<nav class="historial-paginas" aria-label="Páginas del historial"><span>Página <?= $pagina ?> de <?= $paginas ?></span><div><?php foreach(['Anterior'=>$pagina-1,'Siguiente'=>$pagina+1] as $titulo=>$destino):if($destino<1||$destino>$paginas)continue;$parametros=['menu'=>'historial_movimientos','buscar'=>$texto,'accion'=>$accion,'desde'=>$desde,'hasta'=>$hasta,'pagina'=>$destino]; ?><a href="/index.php?<?= $e(http_build_query($parametros)) ?>"><?= $e($titulo) ?></a> <?php endforeach; ?></div></nav></section>
